import { Router } from "express";
import { createMaterial, listAlerts, listMaterials, registerMovement, updateMaterial, } from "../controllers/materialController.js";
import { requireAdmin, requireAuth } from "../middleware/auth.js";
import { asyncHandler } from "../middleware/error.js";
const router = Router();
router.get("/", requireAuth, requireAdmin, asyncHandler(listMaterials));
router.post("/", requireAuth, requireAdmin, asyncHandler(createMaterial));
router.patch("/:id", requireAuth, requireAdmin, asyncHandler(updateMaterial));
router.post("/:id/movements", requireAuth, requireAdmin, asyncHandler(registerMovement));
router.get("/alerts", requireAuth, requireAdmin, asyncHandler(listAlerts));
export default router;
